sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading || newValue === '') {
        return;
    }

    var ga = new GlideAjax('LocationCoordinatesAjax');

    ga.addParam('sysparm_name', 'getCoordinates');
    ga.addParam('sysparm_location', newValue);

    ga.getXMLAnswer(function(response) {

        if (!response) {
            g_form.setValue('latitude', '');
            g_form.setValue('longitude', '');
            g_form.setValue('district', '');
            g_form.setValue('state', '');
            return;
        }

        var data = JSON.parse(response);

        // Latitude and Longitude
        g_form.setValue('latitude', data.latitude);
        g_form.setValue('longitude', data.longitude);

        // District and State
        g_form.setValue('district', data.district);
        g_form.setValue('state', data.state);

		// Map Location
		g_form.setValue('map_location', data.sys_id);
    });
}
